<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import Spinner from '$lib/components/common/Spinner.svelte';
 import StarliMailSettings from './StarliMailSettings.svelte';
 import StarliMailActions from './StarliMailActions.svelte';
 let connection:any=null,editingId='',editingRevision=0,markBusy=false;
 const sendKeys:Record<string,string>={};
 let folder='inbox',messages:any[]=[],selected:any=null,search='',offset=0,total=0,loading=false,busy=false,error='',notice='',compose=false,to='',subject='',body='',draftKey='',epoch=0;
 const headers=()=>({Authorization:`Bearer ${localStorage.token}`,'Content-Type':'application/json'});
 function unpack(data:any){if(data.isError)throw Error((data.content??[]).filter((v:any)=>v.type==='text').map((v:any)=>v.text).join(' ')||'Mailbox tool failed');const parts=(data.content??[]).filter((v:any)=>v.type==='text');if(parts.length){try{return JSON.parse(parts[0].text);}catch{return {message:parts[0].text};}}return data;}
 async function tool(name:string,args:any,key?:string){const r=await fetch('/api/v1/starli/tools/invoke',{method:'POST',headers:headers(),body:JSON.stringify({tool:name,args,...(key?{operationKey:key}:{})})});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'Mailbox request failed ('+r.status+')');return unpack(d);}
 async function load(next=0){try{const r=await fetch('/api/v1/starli/mail',{headers:headers()});if(r.ok)connection=await r.json();}catch{}if(['connection','reviews'].includes(folder)){loading=false;return;}const seq=++epoch;loading=true;error='';try{let d:any;if(folder==='drafts'){const r=await fetch('/api/v1/starli/customer-data/mailbox/drafts',{headers:headers()});if(!r.ok)throw Error('Could not load saved drafts');const all=await r.json();const filtered=(all.items??[]).filter((v:any)=>(String(v.subject??'')+' '+String(v.textBody??'')).toLowerCase().includes(search.toLowerCase()));d={messages:filtered.slice(next,next+30).map((v:any)=>({...v,_draft:true,from:v.fromAccount,snippet:String(v.textBody??'').slice(0,160)})),total:filtered.length};}else d=await tool('inbox_search',{search:search.trim(),offset:next,limit:30});if(seq!==epoch)return;messages=d.messages??d.items??[];total=Number(d.total??messages.length);offset=next;}catch(e){if(seq===epoch)error=(e as Error).message;}finally{if(seq===epoch)loading=false;}}
 async function open(message:any){busy=true;error='';try{if(message._draft)selected=message;else{const r=await fetch('/api/v1/starli/customer-data/mailbox/messages/'+encodeURIComponent(message.id),{headers:headers()});if(!r.ok)throw Error('Message unavailable');selected=await r.json();}compose=false;}catch(e){error=(e as Error).message;}finally{busy=false;}}
 function newDraft(reply=false){editingId='';editingRevision=0;compose=true;to=reply?String(selected?.from?.address??selected?.from??''):'';subject=reply?'Re: '+String(selected?.subject??'').replace(/^Re:\s*/i,''):'';body='';draftKey=crypto.randomUUID();notice='';}
 async function save(){if(!to.trim()||!subject.trim()||!body.trim())return;busy=true;error='';try{const args:any={to:to.split(/[,;\n]/).map(s=>s.trim()).filter(Boolean),subject:subject.trim(),bodyText:body.trim()};if(selected?.id&&subject.startsWith('Re: '))args.inReplyToMessageId=selected.id;if(editingId){args.draftId=editingId;args.expectedRevision=editingRevision;args.textBody=args.bodyText;delete args.bodyText;delete args.inReplyToMessageId;}const d=await tool(editingId?'mailbox_draft_update':'outreach_create_draft',args,draftKey);notice='Draft saved. No email was sent.';compose=false;folder='drafts';await load(0);}catch(e){error=(e as Error).message;}finally{busy=false;}}
 function display(value:any){if(Array.isArray(value))return value.map(display).join(', ');return typeof value==='object'&&value?value.name?value.name+' <'+value.address+'>':String(value.address??''):String(value??'');}
 function editDraft(){if(!selected?._draft)return;editingId=selected.id;editingRevision=selected.revision??1;to=(selected.to??[]).map((v:any)=>v.address).join(', ');subject=selected.subject??'';body=selected.textBody??'';draftKey=crypto.randomUUID();compose=true;}
 async function prepareSend(){if(!selected?._draft)return;busy=true;error='';try{await tool('mail_prepare_send',{draftId:selected.id},sendKeys[selected.id+':'+selected.revision]??=crypto.randomUUID());folder='reviews';compose=false;notice='Review the exact sender, recipients and message before sending.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function syncInbox(){busy=true;error='';try{const r=await fetch('/api/v1/starli/mail/sync',{method:'POST',headers:headers(),body:JSON.stringify({limit:20})});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'Synchronization failed');notice=String(d.messagesAdded??0)+' messages synchronized. Remote messages were not marked read.';folder='inbox';await load(0);}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function markRead(){if(!selected||selected._draft)return;markBusy=true;error='';try{await tool(connection?.connected&&selected.uid?'mail_mark_read':'mailbox_mark_read',{messageId:selected.id,isRead:!selected.isRead},crypto.randomUUID());selected={...selected,isRead:!selected.isRead};}catch(e){error=(e as Error).message;}finally{markBusy=false;}}
 function ask(){window.dispatchEvent(new CustomEvent('starli-compose',{detail:{prompt:selected?'Draft a reply to my mailbox message '+selected.id+'. Save a draft; do not send yet.':'Help me draft an email for my client and save it to my mailbox.'}}));notice='Continue in the chat composer.';}
 onMount(()=>{void load();});onDestroy(()=>epoch++);
</script>
<section class="flex h-full flex-col p-4 md:p-6">
 <header class="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h1 class="text-2xl font-semibold">Mailbox</h1><p class="mt-2 text-sm text-gray-500">Read synchronized messages and work on replies with Starli in chat.</p></div><div class="flex gap-2"><button class="rounded-lg bg-gray-100 px-3 py-2 text-sm dark:bg-gray-800" on:click={ask}>Ask Starli</button><button class="rounded-lg bg-gray-900 px-3 py-2 text-sm text-white dark:bg-gray-100 dark:text-gray-900" on:click={()=>newDraft(false)}>New draft</button></div></header>
 <nav class="mb-3 flex gap-1" aria-label="Mailbox folders">{#each ['inbox','drafts','reviews','connection'] as value}<button class="rounded-lg px-3 py-1.5 text-xs {folder===value?'bg-gray-100 dark:bg-gray-800':'text-gray-500'}" on:click={()=>{folder=value;selected=null;void load(0);}}>{value==='inbox'?'Messages':value==='drafts'?'Drafts':value==='reviews'?'Send reviews':'Connection'}</button>{/each}</nav>
 {#if folder==='connection'}<StarliMailSettings on:change={(e)=>connection=e.detail}/>
 {:else if folder==='reviews'}<StarliMailActions on:change={()=>{void load();}}/>
 {:else}
 <div class="mb-3 flex items-center justify-between gap-2 text-xs text-gray-500"><span>{connection?.connected?connection.email+' · '+connection.status:'Connect your own mailbox to synchronize and send.'}</span><button disabled={!connection?.connected||busy} class="rounded-lg bg-gray-100 px-3 py-1.5 disabled:opacity-40 dark:bg-gray-800" on:click={syncInbox}>Sync inbox</button></div>
 <form class="mb-4 flex gap-2" on:submit|preventDefault={()=>load(0)}><input aria-label="Search mailbox" bind:value={search} placeholder="Search messages" class="min-w-0 flex-1 rounded-lg bg-gray-50 px-3 py-2 text-sm dark:bg-gray-850"/><button class="rounded-lg bg-gray-100 px-3 py-2 text-sm dark:bg-gray-800">Search</button></form>
 {#if error}<p role="alert" class="mb-3 text-sm text-red-600 dark:text-red-400">{error}</p>{/if}
 {#if notice}<p role="status" class="mb-3 text-sm text-gray-500">{notice}</p>{/if}
 <div class="grid min-h-0 flex-1 gap-4 lg:grid-cols-2">
  <div class="overflow-auto rounded-xl border border-gray-100 dark:border-gray-800">
   {#if loading}<div class="p-5"><Spinner/></div>{/if}
   {#each messages as message (message.id)}<button class="block w-full border-b border-gray-100 p-4 text-left hover:bg-gray-50 dark:border-gray-800 dark:hover:bg-gray-850" on:click={()=>open(message)}><div class="flex justify-between gap-3"><span class="truncate text-sm font-medium">{message.subject||'No subject'}</span><span class="shrink-0 text-xs text-gray-500">{message.status??''}</span></div><p class="mt-1 truncate text-xs text-gray-500">{display(message.from)}</p><p class="mt-2 line-clamp-2 text-sm text-gray-500">{message.snippet??''}</p></button>
   {:else}{#if !loading}<p class="p-6 text-sm text-gray-500">{folder==='drafts'?'No saved drafts in this workspace.':'No synchronized messages in this workspace.'} Messages from other customer accounts are kept separate.</p>{/if}{/each}
   <div class="flex items-center justify-between p-3 text-xs text-gray-500"><button disabled={offset===0||loading} class="disabled:opacity-40" on:click={()=>load(Math.max(0,offset-30))}>Previous</button><span>{total} messages</span><button disabled={offset+messages.length>=total||loading} class="disabled:opacity-40" on:click={()=>load(offset+30)}>Next</button></div>
  </div>
  <aside class="overflow-auto rounded-xl border border-gray-100 p-4 dark:border-gray-800">
   {#if compose}<form class="space-y-3" on:submit|preventDefault={save}><h2 class="text-sm font-medium">{editingId?'Edit draft':'Email draft'}</h2><label class="block text-xs text-gray-500">To<input required type="text" bind:value={to} placeholder="client@example.com" class="mt-1 w-full rounded-lg bg-gray-50 px-3 py-2 text-sm text-gray-900 dark:bg-gray-850 dark:text-gray-100"/></label><label class="block text-xs text-gray-500">Subject<input required bind:value={subject} class="mt-1 w-full rounded-lg bg-gray-50 px-3 py-2 text-sm text-gray-900 dark:bg-gray-850 dark:text-gray-100"/></label><label class="block text-xs text-gray-500">Message<textarea required rows="12" bind:value={body} class="mt-1 w-full rounded-lg bg-gray-50 px-3 py-2 text-sm text-gray-900 dark:bg-gray-850 dark:text-gray-100"/></label><div class="flex gap-2"><button disabled={busy} class="rounded-lg bg-gray-900 px-3 py-2 text-sm text-white disabled:opacity-40 dark:bg-gray-100 dark:text-gray-900">{busy?'Saving…':'Save draft'}</button><button type="button" class="rounded-lg bg-gray-100 px-3 py-2 text-sm dark:bg-gray-800" on:click={()=>compose=false}>Cancel</button></div><p class="text-xs text-gray-500">Saving a draft does not send an email.</p></form>
   {:else if selected}<header class="mb-4"><h2 class="font-medium">{selected.subject||'No subject'}</h2><p class="mt-2 text-xs text-gray-500">From {display(selected.from)}</p><p class="mt-1 text-xs text-gray-500">To {display(selected.to)}</p><p class="mt-1 text-xs text-gray-500">{selected.date??''} · {selected.status??''}</p></header><div class="whitespace-pre-wrap break-words text-sm">{selected.textBody??'No text body available.'}</div><div class="mt-5 flex gap-2">{#if selected._draft}<button disabled={busy} class="rounded-lg bg-gray-100 px-3 py-2 text-sm dark:bg-gray-800" on:click={editDraft}>Edit draft</button><button disabled={busy} class="rounded-lg bg-gray-900 px-3 py-2 text-sm text-white disabled:opacity-40 dark:bg-gray-100 dark:text-gray-900" on:click={prepareSend}>Review send</button>{:else}<button disabled={markBusy} class="rounded-lg bg-gray-100 px-3 py-2 text-sm dark:bg-gray-800" on:click={markRead}>{selected.isRead?'Mark unread':'Mark read'}</button><button class="rounded-lg bg-gray-100 px-3 py-2 text-sm dark:bg-gray-800" on:click={()=>newDraft(true)}>Reply draft</button>{/if}<button class="rounded-lg bg-gray-100 px-3 py-2 text-sm dark:bg-gray-800" on:click={ask}>Draft with Starli</button></div>{#if selected.attachments?.length}<div class="mt-5"><h3 class="text-xs font-medium">Attachments</h3>{#each selected.attachments as attachment}<p class="mt-2 text-xs text-gray-500">{attachment.filename} · {attachment.byteSize} bytes</p>{/each}</div>{/if}
   {:else}<p class="text-sm text-gray-500">Select a message or ask Starli to prepare a draft in chat.</p>{/if}
  </aside>
 </div>
 {/if}
</section>
